import{Ct as e,Lt as t,St as n,Vt as r,Xt as i,_t as a,bt as o,n as s,xt as c}from"./chunks/framework.CpAKRyMe.js";var l=JSON.parse(`{"title":"示教-复现（四）：分级验证、现场踩坑与复盘","description":"让人敢按「去程」按钮的工程约束：V0–V4 分级验证、dry-run 的两个坑、发布者争抢、参数继承链与结构化日志，以及仍未解决的问题","frontmatter":{"title":"示教-复现（四）：分级验证、现场踩坑与复盘","category":["机器人","ROS2"],"tag":["现场验证","工程实践","复盘"],"description":"让人敢按「去程」按钮的工程约束：V0–V4 分级验证、dry-run 的两个坑、发布者争抢、参数继承链与结构化日志，以及仍未解决的问题","date":"2026-11-22T18:10:00.000Z","updated":"2026-11-22T18:10:00.000Z","cover":"lucide:clipboard-check","ai":true,"breadcrumbs":[{"title":"首页","link":"/"},{"title":"机器人","link":"/articles/robotics"},{"title":"示教-复现（四）：分级验证、现场踩坑与复盘","link":""}]},"headers":[],"relativePath":"articles/robotics/navigation/teach-repeat-04-validation.md","filePath":"articles/robotics/navigation/teach-repeat-04-validation.md"}`),u={name:`articles/robotics/navigation/teach-repeat-04-validation.md`};function d(s,l,u,d,f,p){let m=r(`VPNolebaseInlineLinkPreview`);return t(),o(`div`,null,[l[4]||=c(`<h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>前三篇是算法：免标定、收敛、降级。这一篇是把同一套代码放到真实场地上反复跑，决定它能不能被信任的，是验证顺序和日志。</p><h2 id="一、分级验证-不许跳级" tabindex="-1">一、分级验证，不许跳级 <a class="header-anchor" href="#一、分级验证-不许跳级" aria-label="Permalink to “一、分级验证，不许跳级”">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>内容</th><th>车</th></tr></thead><tbody><tr><td>V0</td><td>页面 / 检测 / 视频流 / 示教 / 参数保存，控制话题发布者为 0</td><td>不动</td></tr><tr><td>V1</td><td>现场示教，生成设定点文件</td><td>手推</td></tr><tr><td>V2</td><td>架空干跑：运动原语方向与精度</td><td>架空</td></tr><tr><td><strong>V3</strong></td><td>推偏 20 cm，只跑伺服，看能否回原位</td><td>短距</td></tr><tr><td>V4</td><td>全程往返，量重复性</td><td>全程</td></tr></tbody></table><p>V3 最关键：它直接检验示教-复现这个假设成不成立，先 V3 再 V4，不要一上来跑 18 m。V2 也证明过价值：架空跑 90° 旋转时发现「转错方向也会达标」的判据缺陷，如果直接上车就是一次 10 倍超转。</p><h2 id="二、dry-run-的两个坑" tabindex="-1">二、dry-run 的两个坑 <a class="header-anchor" href="#二、dry-run-的两个坑" aria-label="Permalink to “二、dry-run 的两个坑”">​</a></h2><p><strong>坑一：没有透传。</strong> 顶层脚本带 <code>--dry-run</code>，但调用伺服子进程时没把参数传下去，结果干跑阶段伺服照样驱动车，这是安全漏洞，不是体验问题。</p><p><strong>坑二：干跑仍走闭环。</strong> 更隐蔽：dry-run 时把发布器换成空对象是对的，但闭环退出条件依赖里程计变化。车不动、里程计不变，于是每步都空转到 deadline，干跑必卡死。</p><p>现在的规则写死两条：dry-run 沿调用链逐层透传；dry-run 路径跳过闭环等待，只打印意图。</p><div class="language-python" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> run_servo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(target, dry):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    argv </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [sys.executable, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;servo.py&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, target]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dry:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        argv.append(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--dry-run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)       </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 必须透传，否则干跑会真动车</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> subprocess.call(argv) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h2 id="三、实跑前必查" tabindex="-1">三、实跑前必查 <a class="header-anchor" href="#三、实跑前必查" aria-label="Permalink to “三、实跑前必查”">​</a></h2><p>残留的速度发布者会互相抢，抢不到的那个持续发零速，表现是车不动，很容易被误判成算法问题。每次实跑前跑两条命令：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ef</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;follower|route_http|fixed_route&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # 应为空</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cmd_vel</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                            # Publisher 应为 0</span></span></code></pre></div><p>清理进程时不要用宽泛的 <code>pkill -f &quot;ros2 launch&quot;</code>，会杀掉开机自启的驱动与底盘服务。匹配要精确到可执行文件路径。</p><h2 id="四、参数只能有一条继承链" tabindex="-1">四、参数只能有一条继承链 <a class="header-anchor" href="#四、参数只能有一条继承链" aria-label="Permalink to “四、参数只能有一条继承链”">​</a></h2><p>所有参数来自一份集中式配置文件，由运维脚本 <code>source</code> 后逐层继承到示教页面 → 任务编排 → 伺服/巡线子进程。任何一环手动启动，整条链就静默回落到代码默认值：实测角速度上限变 0.08 而非 0.15、迭代上限变 60 而非 100，行为不对但没有一行报错。</p><p>识别方法只有一个：查进程的 <code>environ</code>，不要读代码猜。</p><p>同理，改动方向要分清：代码是「本机 → 底盘」，示教结果与日志是「底盘 → 本机」。方向搞反，就会出现「改了设定点但行为没变」。</p><h2 id="五、限制与可调范围" tabindex="-1">五、限制与可调范围 <a class="header-anchor" href="#五、限制与可调范围" aria-label="Permalink to “五、限制与可调范围”">​</a></h2><p>现场能改的和改不动的要分清，否则会把「参数没调对」和「物理上做不到」混在一起。</p><table tabindex="0"><thead><tr><th>类别</th><th>项</th><th>说明</th></tr></thead><tbody><tr><td>可现场调</td><td>检测带行数、HSV 阈值、m00 门限系数、速度与增益、三轴容差</td><td>改参数后重启服务生效，不必重示教</td></tr><tr><td>需要重示教</td><td>标签尺寸、相机或分辨率更换、端点位置移动</td><td>测量链变了，旧的 golden 作废</td></tr><tr><td>改不动的</td><td>光照不足、红线镜面反射、横向里程计失真、惯性单元故障、底盘无横移</td><td>只能换方案或改硬件，调参解决不了</td></tr></tbody></table><p>底盘侧的限制也在最后一类。两轮差速没有横移能力，所以「转 90° + 走固定距离」的横移写法在里程计失真时不可用；纯轮式里程计横移时读数偏差 0.78x–5.97x；惯性单元 Z 轴失效让融合里程计不可用。这三条决定了横向只能靠标签连续反馈修正；长距离的中间段没有外部基准，要靠巡线或地面布点补上。</p><h2 id="六、日志要能事后复算" tabindex="-1">六、日志要能事后复算 <a class="header-anchor" href="#六、日志要能事后复算" aria-label="Permalink to “六、日志要能事后复算”">​</a></h2><p>巡线每个控制周期写一行 CSV：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>t, seq, mode, detected, erro_px, m00, odom_x, odom_y, odom_yaw,</span></span>
<span class="line"><span>yaw_ref, traveled, v, w, remaining</span></span></code></pre></div><p>外加可选的定时整帧 jpg（保留最新两次）和一份 <code>summary.json</code>（退出码、耗时、检出率、各模式驻留时长、被门限拒帧计数）。</p><p>这些字段是复盘时的依据：中远场红区那次跑偏，是靠 <code>m00</code> 与 <code>erro</code> 的时序定位到红区侵入采样带；符号错误那次发散，是靠 <code>dyaw</code> 与 <code>w</code> 的符号对照确认越转越偏。没有这些数据，偶发跑偏只能靠猜。</p><h2 id="七、结果与没解决的问题" tabindex="-1">七、结果与没解决的问题 <a class="header-anchor" href="#七、结果与没解决的问题" aria-label="Permalink to “七、结果与没解决的问题”">​</a></h2><p><strong>已达成的：</strong></p><ul><li>短距方案（直行 + 原地掉头）去程/返程两轮验证通过，两端伺服收敛，终点 ±2 cm / ±1°；这是目前实际使用的方案；</li><li>长距巡线只跑通过一次去程（18 m、检出 95%、终点伺服收敛），回程不稳定，方案暂停；</li><li>掉头位姿改为示教相对角（实测 174.18° / 168.67°，而非名义 180°），跨重启有效，修掉固定 180° 带来的约 10° 几何偏差；</li><li>单测覆盖控制律、状态机、污染门限、运动原语标定与真实污染帧回归。</li></ul><p><strong>还没解决的：</strong></p><ul><li><strong>回程巡线的红线镜面反射方向性</strong>。同一根红线，反方向行驶时饱和度下降（S 中位数 80 → 73，S ≥ 100 的像素 1792 → 597），丢线后容易追着右侧反光误检（偏差 +246 px）转几十度。这是物理问题，根治要换哑光胶带或补光；代码侧的「重捕获门槛提高」讨论过但没实施。</li><li><strong>横向里程计不可靠</strong>。纯轮式里程计在横移时读数失真 0.78x–5.97x，所以「转 90° + 走固定距离」这类横移原语被整体弃用，横向只能靠标签的连续反馈来修，这也限制了标签丢失时的兜底能力。</li><li><strong>惯性单元待修</strong>。修好后应把里程计源切回融合版本，旋转闭环会更稳。</li></ul><h2 id="八、可以搬走的五条" tabindex="-1">八、可以搬走的五条 <a class="header-anchor" href="#八、可以搬走的五条" aria-label="Permalink to “八、可以搬走的五条”">​</a></h2><ol><li>有确定性系统误差的传感器，可以先考虑「同一个错犯两次」，再考虑标定。前提是测量链不变、示教与复现的相对位姿一致。</li><li>控制律里每个角度都要有明确分工：误差方位角决定前进方向，实测方位角决定转向，示教方位角定义平衡点。混用会同时得到饱和、震荡和稳态误差。</li><li>定步长容易过冲。按余差比例给预算、时长取先到者、每步只吃一半，收敛就单调了。</li><li>死区补偿要连续、要分场景。阶跃式抬升会把小误差放大成 bang-bang；在已经在动的弧行步里抬角速度，等于把控制器换成开关控制器。</li><li>降级路径要和主路径一样被测试。「丢线 2 s 后按里程计航向直行」这类支路必须能单独触发、单独验证。</li></ol><h2 id="系列" tabindex="-1">系列 <a class="header-anchor" href="#系列" aria-label="Permalink to “系列”">​</a></h2>`,35),a(`ul`,null,[a(`li`,null,[e(m,{href:`/articles/robotics/navigation/teach-repeat-01-principle.html`},{default:i(()=>[...l[0]||=[n(`（一）原理与测量：不标定相机也能做到 ±2cm 定点`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/navigation/teach-repeat-02-servo.html`},{default:i(()=>[...l[1]||=[n(`（二）伺服：一条控制律同时收敛 x/z/yaw`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/navigation/teach-repeat-03-travel.html`},{default:i(()=>[...l[2]||=[n(`（三）行驶：三融合状态机与丢线兜底`,-1)]]),_:1})]),a(`li`,null,[e(m,{href:`/articles/robotics/navigation/teach-repeat-04-validation.html`},{default:i(()=>[...l[3]||=[n(`（四）验证：分级验证、现场踩坑与复盘`,-1)]]),_:1})])])])}var f=s(u,[[`render`,d]]);export{l as __pageData,f as default};